from z3 import *
import itertools

def solve():
    n = 15
    E = 23

    s = Solver()
    edges = {}
    for i in range(n):
        for j in range(i+1, n):
            edges[(i,j)] = Bool(f"e_{i}_{j}")

    # At least 23 edges
    s.add(Sum([If(edges[(i,j)], 1, 0) for i in range(n) for j in range(i+1, n)]) >= E)

    # length 3
    for c in itertools.combinations(range(n), 3):
        s.add(Not(And(edges[(c[0],c[1])], edges[(c[0],c[2])], edges[(c[1],c[2])])))

    # length 4
    for c in itertools.permutations(range(n), 4):
        if c[0] < c[1] and c[0] < c[2] and c[0] < c[3]:
            e1 = edges[tuple(sorted((c[0], c[1])))]
            e2 = edges[tuple(sorted((c[1], c[2])))]
            e3 = edges[tuple(sorted((c[2], c[3])))]
            e4 = edges[tuple(sorted((c[3], c[0])))]
            s.add(Not(And(e1, e2, e3, e4)))

    # length 5
    for c in itertools.combinations(range(n), 5):
        for p in itertools.permutations(c):
            if p[0] == min(p) and p[1] < p[4]:
                e1 = edges[tuple(sorted((p[0], p[1])))]
                e2 = edges[tuple(sorted((p[1], p[2])))]
                e3 = edges[tuple(sorted((p[2], p[3])))]
                e4 = edges[tuple(sorted((p[3], p[4])))]
                e5 = edges[tuple(sorted((p[4], p[0])))]
                s.add(Not(And(e1, e2, e3, e4, e5)))

    # length 6
    for c in itertools.combinations(range(n), 6):
        for p in itertools.permutations(c):
            if p[0] == min(p) and p[1] < p[5]:
                e1 = edges[tuple(sorted((p[0], p[1])))]
                e2 = edges[tuple(sorted((p[1], p[2])))]
                e3 = edges[tuple(sorted((p[2], p[3])))]
                e4 = edges[tuple(sorted((p[3], p[4])))]
                e5 = edges[tuple(sorted((p[4], p[5])))]
                e6 = edges[tuple(sorted((p[5], p[0])))]
                s.add(Not(And(e1, e2, e3, e4, e5, e6)))

    s.set("timeout", 30000)
    res = s.check()
    print(res)
    if res == sat:
        m = s.model()
        ans = []
        for i in range(n):
            for j in range(i+1, n):
                if is_true(m[edges[(i,j)]]):
                    ans.extend([i, j])
        print(ans)

solve()

from pysat.solvers import Glucose3
from pysat.card import CardEnc, EncType
import itertools

def solve():
    n = 15

    # Variables for edges
    def var(i, j):
        if i > j:
            i, j = j, i
        return i * n + j + 1

    solver = Glucose3()

    # Girth >= 7 means no cycles of length 3, 4, 5, 6
    # length 3
    for c in itertools.combinations(range(n), 3):
        solver.add_clause([-var(c[0], c[1]), -var(c[0], c[2]), -var(c[1], c[2])])

    # length 4
    for c in itertools.permutations(range(n), 4):
        if c[0] < c[1] and c[0] < c[2] and c[0] < c[3]:
            solver.add_clause([-var(c[0], c[1]), -var(c[1], c[2]), -var(c[2], c[3]), -var(c[3], c[0])])

    # length 5
    for c in itertools.combinations(range(n), 5):
        for p in itertools.permutations(c):
            if p[0] == min(p) and p[1] < p[4]:
                solver.add_clause([-var(p[0], p[1]), -var(p[1], p[2]), -var(p[2], p[3]), -var(p[3], p[4]), -var(p[4], p[0])])

    # length 6
    for c in itertools.combinations(range(n), 6):
        for p in itertools.permutations(c):
            if p[0] == min(p) and p[1] < p[5]:
                solver.add_clause([-var(p[0], p[1]), -var(p[1], p[2]), -var(p[2], p[3]), -var(p[3], p[4]), -var(p[4], p[5]), -var(p[5], p[0])])

    # At least 23 edges
    edges = []
    for i in range(n):
        for j in range(i+1, n):
            edges.append(var(i, j))

    cnf = CardEnc.atleast(lits=edges, bound=23, encoding=EncType.seqcounter)
    for clause in cnf.clauses:
        solver.add_clause(clause)

    print("Solving...")
    res = solver.solve()
    print("Result:", res)
    if res:
        model = solver.get_model()
        ans = []
        for i in range(n):
            for j in range(i+1, n):
                if model[var(i, j) - 1] > 0:
                    ans.extend([i, j])
        print(ans)

solve()

